// newLearnConfig returns the per-CLI entity extractor Config the
// teach / recall / normalize call sites pass into the learn package.
// Reads the printed-CLI's spec.Learn.TickerPatterns, Stopwords, and
// Synonyms; patterns that fail to compile at runtime (defense in
// depth — spec parse already validated them) log a warning and are
// skipped. Declared synonyms register on both the returned Config and
// the store package's write-side normalizer.
func newLearnConfig() *entities.Config {
	cfg := entities.NewConfig()
	// No ticker pattern is registered. PSX symbols are ALL-CAPS
	// alphanumeric (HUBC, OGDC, FFC), which entities.Extract rule 2
	// already classifies as entities without a pattern. The spec's
	// declared `^[a-z0-9]{2,12}$` was inverted: matchesTicker runs on
	// the RAW token before lowercasing, so it never matched a real
	// symbol and matched every ordinary lowercase word instead --
	// which emptied QueryFamily and made every seeded playbook
	// unreachable at recall time.
	// Spec-declared same-referent synonym folds, registered on BOTH
	// normalizers: the entities.Config drives the read side (recall
	// family keys) and store.RegisterQuerySynonyms the write side
	// (teach query patterns). One map, two registrations — the
	// two-normalizer symmetry the learn loop's key space depends on.
	learnSynonyms := map[string]string{
		"foreign flows":    "fipi",
		"foreigners":       "fipi",
		"local flows":      "lipi",
		"locals":           "lipi",
		"margin financing": "mts",
		"most recent":      "latest",
		"short interest":   "slb",
	}
	cfg.RegisterSynonyms(learnSynonyms)
	store.RegisterQuerySynonyms(learnSynonyms)
	return cfg
}

// initLearn seeds the entity_lookups table from the spec.Learn.
// EntityLookupSeeds declaration. INSERT OR IGNORE on the store side
// makes this idempotent — calling it twice produces the same DB state
// as calling it once. An empty seed map is a no-op (returns nil).
func initLearn(ctx context.Context, db *sql.DB) error {
	_ = ctx
	seeds := map[string][]lookups.SeedConfig{
		"investor_type": {
			{Canonical: "101", Values: []string{"all", "everyone", "all-investors"}},
			{Canonical: "FI", Values: []string{"foreign individual", "foreign individuals", "foreign retail"}},
			{Canonical: "FC", Values: []string{"foreign corporates", "foreign corporate", "foreign institutions", "foreign institutional"}},
			{Canonical: "FOP", Values: []string{"overseas pakistani", "overseas pakistanis", "non-resident", "nrp"}},
			{Canonical: "FN", Values: []string{"fipi net", "foreign net", "net foreign"}},
			{Canonical: "LBD", Values: []string{"banks", "banks/dfi", "banks dfi", "dfi", "commercial banks"}},
			{Canonical: "LBP", Values: []string{"brokers", "broker proprietary trading", "broker prop", "proprietary"}},
			{Canonical: "LC", Values: []string{"companies", "corporates", "local companies"}},
			{Canonical: "LI", Values: []string{"individuals", "retail", "local individuals"}},
			{Canonical: "LN", Values: []string{"lipi net", "local net", "net local"}},
			{Canonical: "LMF", Values: []string{"mutual funds", "mutual fund", "funds", "mf"}},
			{Canonical: "LNB", Values: []string{"nbfc", "non-banking finance", "non banking finance companies"}},
			{Canonical: "IC", Values: []string{"insurance", "insurance companies", "insurers"}},
			{Canonical: "LOO", Values: []string{"other organization", "other organisations", "other", "others"}},
		},
		"market_segment": {
			{Canonical: "EQUITY", Values: []string{"equities", "equity market", "stock market", "cash market"}},
			{Canonical: "DEBT", Values: []string{"debt market", "bonds", "fixed income"}},
		},
	}
	if _, err := lookups.SeedFromConfig(db, seeds); err != nil {
		return fmt.Errorf("initLearn: seed entity_lookups: %w", err)
	}
	return nil
}

// learnInitOnce gates runLearnInitOnce so the seed pass happens at
// most once per CLI process. The sync.Once keeps the cost off the
// hot path for repeat command invocations within an MCP session.
var learnInitOnce sync.Once

// runLearnInitOnce opens the canonical store path, fires initLearn
// once per process, and downgrades any failure to a stderr warning.
// Per the self-learning loop's soft-validation contract, a seed
// failure must never abort the CLI — the recall path returns the
// empty envelope if entity_lookups is missing rows, which is the
// same behavior an opt-out CLI sees.
func runLearnInitOnce(ctx context.Context) {
	learnInitOnce.Do(func() {
		dbPath := defaultDBPath("nccpl-pp-cli")
		s, err := store.OpenWithContext(ctx, dbPath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "warning: nccpl-pp-cli: learn init: open store: %v\n", err)
			return
		}
		defer s.Close()
		if err := initLearn(ctx, s.DB()); err != nil {
			fmt.Fprintf(os.Stderr, "warning: nccpl-pp-cli: learn init: %v\n", err)
		}
	})
}

